-- =====================================================================================
--  P49 — الجزء 2/2: بذر «استبيان نهاية البرنامج (عام)» (قالب END افتراضي + 17 سؤالًا)
--  © 2026 د. أحمد محمد عبدالعزيز بدوي — جميع الحقوق محفوظة
--  نفّذه بعد الجزء 1/2 (في تشغيل منفصل). آمن لإعادة التنفيذ: لا يُنشئ قالبًا ثانيًا ولا يكرّر الأسئلة (حسب question_key).
--  المصدر الوحيد للنصوص: lib/evaluation/links.ts → END_SURVEY_SEED
-- =====================================================================================
do $$
declare
  v_tpl uuid; v_opts_type text; q jsonb; v_opts text; n int := 0;
  v_rows jsonb := '[{"key":"end_q01_objectives","kind":"LIKERT_5","ar":"كانت أهداف الدورة واضحة","en":"The course objectives were clear","section_ar":"الدورة ومحتواها","section_en":"The course and its content","required":true,"options":[],"max":5,"order":1},{"key":"end_q02_workload","kind":"LIKERT_5","ar":"كان مقدار الكتابة أو الأعمال الصفية الأخرى التي طُلب منك القيام بها كافياً","en":"The amount of writing or other class work required was adequate","section_ar":"الدورة ومحتواها","section_en":"The course and its content","required":true,"options":[],"max":5,"order":2},{"key":"end_q03_presentations","kind":"LIKERT_5","ar":"تشرح عروض الدورة التدريبية مفاهيم الدورة بشكل فعال","en":"The course presentations explained the concepts effectively","section_ar":"الدورة ومحتواها","section_en":"The course and its content","required":true,"options":[],"max":5,"order":3},{"key":"end_q04_materials","kind":"LIKERT_5","ar":"كانت الحقيبة التدريبية ومصادر التعلم مفيدة للدورة","en":"The training kit and learning resources were useful","section_ar":"الدورة ومحتواها","section_en":"The course and its content","required":true,"options":[],"max":5,"order":4},{"key":"end_q05_technology","kind":"LIKERT_5","ar":"عزز استخدام التكنولوجيا خلال الدورة من فهمي للموضوع","en":"The use of technology during the course enhanced my understanding","section_ar":"الدورة ومحتواها","section_en":"The course and its content","required":true,"options":[],"max":5,"order":5},{"key":"end_q06_quality","kind":"LIKERT_5","ar":"كانت مواد الدورة التدريبية عالية الجودة ومناسبة للتعلم","en":"The course materials were high quality and suitable for learning","section_ar":"الدورة ومحتواها","section_en":"The course and its content","required":true,"options":[],"max":5,"order":6},{"key":"end_q07_motivation","kind":"LIKERT_5","ar":"قام المدرب بزيادة الحافز عندي للدراسة","en":"The trainer increased my motivation to study","section_ar":"المدرّب","section_en":"The trainer","required":true,"options":[],"max":5,"order":7},{"key":"end_q08_depth","kind":"LIKERT_5","ar":"قام المدرب بشرح المعلومات بعمق وتفصيل مناسب","en":"The trainer explained the information in appropriate depth and detail","section_ar":"المدرّب","section_en":"The trainer","required":true,"options":[],"max":5,"order":8},{"key":"end_q09_enthusiasm","kind":"LIKERT_5","ar":"كان المدرب متحمس و مهتم بالتدريب","en":"The trainer was enthusiastic and engaged in the training","section_ar":"المدرّب","section_en":"The trainer","required":true,"options":[],"max":5,"order":9},{"key":"end_q10_answers","kind":"LIKERT_5","ar":"هل يمكنك الحصول على إجابات واضحة لأسئلتك من المدرب؟","en":"Could you get clear answers to your questions from the trainer?","section_ar":"المدرّب","section_en":"The trainer","required":true,"options":[],"max":5,"order":10},{"key":"end_q11_readiness","kind":"LIKERT_5","ar":"هل كان المدرب مستعدًا للإجابة على جميع الاستفسارات المتعلقة بالدورة؟","en":"Was the trainer ready to answer all course-related enquiries?","section_ar":"المدرّب","section_en":"The trainer","required":true,"options":[],"max":5,"order":11},{"key":"end_q12_pace","kind":"LIKERT_5","ar":"هل كانت السرعة التي قدم بها المدرب مادة الدورة التدريبية صحيحة؟","en":"Was the pace at which the trainer delivered the course material right?","section_ar":"المدرّب","section_en":"The trainer","required":true,"options":[],"max":5,"order":12},{"key":"end_q13_improve_trainer","kind":"LONG_TEXT","ar":"ما الذي تنصح به لتحسين أداء المعلم؟","en":"What would you recommend to improve the trainer''s performance?","section_ar":"رأيك","section_en":"Your opinion","required":false,"options":[],"max":null,"order":13},{"key":"end_q14_strengths","kind":"LONG_TEXT","ar":"ما هي نقاط القوة الرئيسية لهذه الدورة؟","en":"What are the main strengths of this course?","section_ar":"رأيك","section_en":"Your opinion","required":false,"options":[],"max":null,"order":14},{"key":"end_q15_improvements","kind":"LONG_TEXT","ar":"ما هي النقاط التي تحتاج الى تحسين في هذه الدورة؟","en":"What needs improvement in this course?","section_ar":"رأيك","section_en":"Your opinion","required":false,"options":[],"max":null,"order":15},{"key":"end_q16_overall","kind":"SINGLE_CHOICE","ar":"ما هو التقييم العام الذي ستعطيه للدورة؟","en":"What overall rating would you give the course?","section_ar":"التقييم العام","section_en":"Overall","required":true,"options":["ممتاز","جيد جدا","جيد","مقبول","ضعيف"],"max":null,"order":16},{"key":"end_q17_nps","kind":"NPS_10","ar":"ما هو مدى ترشيحك لزملائك وعائلتك بالدراسة معنا في الأكاديمية؟ (10 أقصى قيمة و0 أقل قيمة)","en":"How likely are you to recommend studying with us at the academy to your colleagues and family? (10 = highest, 0 = lowest)","section_ar":"الترشيح","section_en":"Recommendation","required":true,"options":[],"max":10,"order":17}]'::jsonb;
begin
  select id into v_tpl from public.evaluation_templates where upper(kind::text) = 'END' order by is_default desc, created_at nulls last limit 1;
  if v_tpl is null then
    insert into public.evaluation_templates (kind, name_ar, name_en, is_default) values ('END', 'استبيان نهاية البرنامج (عام)', 'End-of-program survey (general)', true) returning id into v_tpl;
  else
    update public.evaluation_templates set is_default = true where id = v_tpl;
  end if;
  select data_type into v_opts_type from information_schema.columns where table_schema = 'public' and table_name = 'questions' and column_name = 'options';
  for q in select * from jsonb_array_elements(v_rows) loop
    if exists (select 1 from public.questions where template_id = v_tpl and question_key = q->>'key') then continue; end if;
    if v_opts_type = 'ARRAY' then v_opts := format('array(select jsonb_array_elements_text(%L::jsonb))::text[]', (q->'options')::text);
    elsif v_opts_type in ('jsonb', 'json') then v_opts := format('%L::jsonb', (q->'options')::text);
    else v_opts := format('%L', (q->'options')::text); end if;
    execute format('insert into public.questions (template_id, kind, text_ar, text_en, section_ar, section_en, is_required, options, max_value, order_index, question_key) values (%L, %L, %L, %L, %L, %L, %L, %s, %L, %L, %L)',
      v_tpl, q->>'kind', q->>'ar', q->>'en', q->>'section_ar', q->>'section_en', (q->>'required')::boolean, v_opts, nullif(q->>'max', '')::int, (q->>'order')::int, q->>'key');
    n := n + 1;
  end loop;
  raise notice 'قالب END: % — أسئلة أُضيفت الآن: %', v_tpl, n;
end $$;

-- تشخيص — المتوقَّع: end_templates = 1 · end_default = 1 · end_questions = 17
select
  (select count(*) from public.evaluation_templates where upper(kind::text) = 'END') as end_templates,
  (select count(*) from public.evaluation_templates where upper(kind::text) = 'END' and is_default) as end_default,
  (select count(*) from public.questions q join public.evaluation_templates t on t.id = q.template_id where upper(t.kind::text) = 'END') as end_questions;
